import React from 'react';
import { Link } from 'react-router-dom';
import type { YearPerson } from '../year_types/YearTypes';
import { addToOrder } from '../year_api/YearApi';

export default function YearPersonCard({ person }: { person: YearPerson }) {
  const src = person.image || 'http://localhost:9000/images/default-person.png';

  async function handleAdd(e: React.MouseEvent) {
    e.preventDefault();
    try {
      const resp = await addToOrder(person.id);
      // backend returns {ok: true} on success, or {error: 'auth_required'}
      if (resp && resp.ok) {
        // Обновим страницу, чтобы обновился счётчик корзины
        window.location.reload();
        return;
      }
      if (resp && resp.error === 'auth_required') {
        // перенаправим на логин с возвратом
        const next = encodeURIComponent(window.location.pathname + window.location.search);
        window.location.href = `/accounts/login/?next=${next}`;
        return;
      }
      alert('Не удалось добавить в заявку');
    } catch (err) {
      console.error(err);
      alert('Ошибка при добавлении в заявку');
    }
  }

  return (
    <div className="person-card">
      <div className="card-header">
        <div className="person-name">{person.person_name}</div>
        <button aria-label={"Добавить " + person.person_name} className="expand-btn" onClick={handleAdd}>+</button>
      </div>
      <div className="card-image">
        <img src={src} alt={person.person_name} onError={(e)=>{ (e.currentTarget as HTMLImageElement).src = 'http://localhost:9000/images/default-person.png'; }} />
      </div>
      <div className="card-years">Период: <strong>{person.year_from} — {person.year_to}</strong></div>
      <p>{person.description}</p>
      <hr />
      <div className="card-footer">
        <a className="details-btn" href={`/person/${person.id}`}>Подробнее →</a>
      </div>
    </div>
  );
}
